import{_ as o,o as t,c as r,a0 as a}from"./chunks/framework.C3yZ6M33.js";const u=JSON.parse('{"title":"Engine ops surface","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ops.md","filePath":"reference/ops.md"}'),d={name:"reference/ops.md"};function s(c,e,i,n,l,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="engine-ops-surface" tabindex="-1">Engine ops surface <a class="header-anchor" href="#engine-ops-surface" aria-label="Permalink to &quot;Engine ops surface&quot;">​</a></h1><p><code>tamias-driver-peregrin</code> is a <strong>dual-surface</strong> binary: the pavo view/ops driver <em>and</em> the tamias content-type driver for <code>peregrin-bundle</code>/<code>peregrin-node</code> packages. The engine half exposes the whole <code>peregrin</code> CLI to agents and hosts without shelling out — the ops manifest is <strong>derived from the engine&#39;s own clap tree</strong> (<code>peregrin_cli::cli::command</code>), so a verb can&#39;t exist on the CLI and be missing from the wire surface.</p><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Verb</th><th>What it does</th></tr></thead><tbody><tr><td><code>manifest</code></td><td>Print the driver manifest JSON (pavo discovery probe)</td></tr><tr><td><code>capabilities</code></td><td>Merged pavo + tamias capability payload (<code>types</code>, <code>verbs</code>)</td></tr><tr><td><code>serve</code></td><td>ndjson JSON-RPC on stdio — <code>{&quot;op&quot;:&quot;ops&quot;}</code> answers the ops manifest; <code>{&quot;op&quot;:&quot;query&quot;,&quot;query&quot;:&quot;cli.&lt;verb&gt;&quot;,&quot;params&quot;:{…}}</code> runs one bounded verb</td></tr><tr><td><code>ops</code></td><td>The ops manifest as JSON, standalone</td></tr><tr><td><code>run &lt;argv&gt;</code></td><td>Engine passthrough — <code>tamias-driver-peregrin run version</code> ≡ <code>peregrin version</code> (also the child side of every <code>cli.*</code> query)</td></tr><tr><td><code>cli &lt;argv&gt;</code></td><td>The tamias <code>bins[]</code> shim verb — the <code>peregrin</code> command itself; strips the standard <code>--dir</code>/<code>--name</code> driver flags and runs the rest through <code>peregrin_cli::cli::run_from</code> with inherited stdio</td></tr></tbody></table><h2 id="cli-verb-ops" tabindex="-1"><code>cli.&lt;verb&gt;</code> ops <a class="header-anchor" href="#cli-verb-ops" aria-label="Permalink to &quot;`cli.&lt;verb&gt;` ops&quot;">​</a></h2><p>Every <strong>bounded</strong> CLI verb is an op named <code>cli.&lt;dotted.path&gt;</code> — <code>cli.sessions.list</code>, <code>cli.campaign.validate</code>, <code>cli.version</code>, … Each op carries:</p><ul><li><code>params</code> — typed entries derived from the clap args (<code>arg</code> = required positional, <code>opt</code> = <code>--name &lt;v&gt;</code>/optional positional, <code>flag</code> = <code>--name</code>). Remote verbs take the node target as ordinary params (<code>--node</code>, <code>--token</code>, <code>--agent</code>); env defaults (<code>PEREGRIN_NODE_URL</code>/<code>PEREGRIN_TOKEN</code>) apply when they&#39;re absent. <code>--token</code>/<code>--source-token</code> are marked <code>secret</code> — pass them via params-stdin, not argv.</li><li><code>mutates</code> — <code>false</code> for the read-only set (probes, history readers, <code>campaign.validate</code>, list/export verbs); <code>true</code> for everything that writes node state, local files, or executes workflows.</li></ul><p>A <code>cli.*</code> query re-execs <code>run &lt;argv&gt;</code> in a captured child and returns <code>{op, argv, code, stdout, stderr}</code> — a nonzero <code>code</code> is the engine&#39;s own exit status (e.g. <code>1</code> + the transport error on <code>stderr</code> when no node answers), not a wire failure.</p><h2 id="surfaces-not-ops" tabindex="-1">Surfaces, not ops <a class="header-anchor" href="#surfaces-not-ops" aria-label="Permalink to &quot;Surfaces, not ops&quot;">​</a></h2><p>Unbounded or host-interactive verbs can never be request/response — they never return or need inherited stdio. They ride <code>surfaces</code> instead and are reachable only through <code>run</code>/<code>cli</code> passthrough or a streaming surface driver:</p><ul><li><code>serve</code> — the node daemon itself</li><li><code>campaign.run</code> / <code>campaign.serve</code> — campaign execution and the multi-campaign webhook listener</li><li><code>sessions.attach</code> — interactive live control</li><li><code>sessions.stream</code> / <code>events</code> — live event streams</li></ul><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p>The driver&#39;s optional <code>mcp</code> cargo feature embeds the pavo-driver-kit surface layer, exposing the same ops manifest as MCP tools on stdio — equivalent to the standalone <code>tamias-driver-mcp</code> surface driver minus the PATH/discovery hop. The hand-rolled <code>peregrin-mcp</code> server is <strong>removed</strong>; MCP access, where needed, comes through this generated surface, not a peregrin-owned binary.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./api.html">HTTP API</a> — the <code>/api/*</code> surface remote ops hit</li><li><a href="./distribution.html">Distribution</a> — the tamias verbs around the driver</li><li><a href="./queue-supersede.html">Queue &amp; supersede</a> — run semantics <code>campaign.*</code> gets</li></ul>',15)])])}const m=o(d,[["render",s]]);export{u as __pageData,m as default};
